create or replace function public.assign_technician_atomic(p_job_id uuid,p_technician_id uuid default null)
returns uuid language plpgsql security definer set search_path=public,private,pg_temp as $$
declare v_role text;v_actor uuid;v_job public.jobs%rowtype;v_tech public.users%rowtype;v_skill public.technician_skills%rowtype;v_next_status text;v_target_start timestamptz;v_target_end timestamptz;v_conflict uuid;begin
v_role:=private.current_employee_role();if v_role not in ('owner','manager','csr_dispatch') then raise exception 'Not authorized';end if;select id into v_actor from public.users where auth_user_id=auth.uid() and active=true limit 1;if v_actor is null then raise exception 'Employee identity unavailable';end if;
select * into v_job from public.jobs where id=p_job_id for update;if not found then raise exception 'Job not found';end if;if v_job.status not in ('booked','scheduled','dispatched') then raise exception 'Technician assignment cannot be changed after field work starts or the job is closed';end if;
if p_technician_id is not null then select * into v_tech from public.users where id=p_technician_id and role='technician' and active=true for update;if not found then raise exception 'Active technician required';end if;if v_job.service_type is not null then select * into v_skill from public.technician_skills where technician_id=p_technician_id and skill=v_job.service_type and active=true limit 1;if not found then raise exception 'Technician is not eligible for this service';end if;if v_skill.certification_expires_on is not null and v_skill.certification_expires_on<current_date then raise exception 'Technician certification has expired';end if;end if;
v_target_start:=v_job.scheduled_start;if v_target_start is not null then v_target_end:=coalesce(v_job.scheduled_end,v_target_start+make_interval(mins=>greatest(coalesce(v_job.expected_duration_minutes,120),1)));select j.id into v_conflict from public.jobs j where j.technician_id=p_technician_id and j.id<>p_job_id and j.status in ('booked','scheduled','dispatched') and j.scheduled_start is not null and tstzrange(j.scheduled_start,coalesce(j.scheduled_end,j.scheduled_start+make_interval(mins=>greatest(coalesce(j.expected_duration_minutes,120),1))),'[)') && tstzrange(v_target_start,v_target_end,'[)') order by j.scheduled_start limit 1 for update;if v_conflict is not null then raise exception 'Technician already has an overlapping scheduled job';end if;end if;v_next_status:='dispatched';else v_next_status:='scheduled';end if;
update public.jobs set technician_id=p_technician_id,status=v_next_status where id=p_job_id;insert into public.audit_log(actor_user_id,action,entity_type,entity_id,before_data,after_data) values(v_actor,case when p_technician_id is null then 'unassign_technician' else 'assign_technician' end,'job',p_job_id::text,jsonb_build_object('technician_id',v_job.technician_id,'status',v_job.status),jsonb_build_object('technician_id',p_technician_id,'status',v_next_status,'source','manual_dispatch','schedule_overlap_checked',p_technician_id is not null and v_target_start is not null,'scheduled_start',v_target_start,'scheduled_end',v_target_end));return p_job_id;end;$$;
revoke all on function public.assign_technician_atomic(uuid,uuid) from public;grant execute on function public.assign_technician_atomic(uuid,uuid) to authenticated;